/**
 * Image sizes generated by the CMS; see payload/collections/media.ts.
 * Ordered from the narrowest to the widest.
 */
export const IMAGE_SIZES = {
  thumb: 400,
  card: 800,
  hero: 1920,
} as const;

export type ImageSizeName = keyof typeof IMAGE_SIZES;

interface SizeData {
  url?: string | null;
  width?: number | null;
  height?: number | null;
}

/** The part of a CMS media document needed to render an image. */
export interface MediaImage extends SizeData {
  alt?: string | null;
  blurDataUrl?: string | null;
  sizes?: Partial<Record<ImageSizeName, SizeData | null | undefined>> | null;
}

export interface PickedImage {
  url: string;
  width: number;
  height: number;
}

function usable(size: SizeData | null | undefined): size is PickedImage {
  return Boolean(size?.url && size.width && size.height);
}

/** Path under which the CMS serves uploads; allowed in next.config.ts. */
export const MEDIA_FILE_PATH = "/api/media/file/";

/**
 * The CMS builds file URLs from SITE_URL. next/image accepts its own file
 * route only as a relative path, and SITE_URL is not the visitor's host on
 * preview deployments, so an absolute URL pointing at that route becomes
 * site-relative. Anything else (direct storage URLs, relative paths) is
 * returned unchanged.
 */
export function toSiteRelativeMediaUrl(url: string): string {
  if (!/^https?:\/\//i.test(url) || !URL.canParse(url)) return url;
  const parsed = new URL(url);
  return parsed.pathname.startsWith(MEDIA_FILE_PATH)
    ? `${parsed.pathname}${parsed.search}`
    : url;
}

/**
 * The requested size when the CMS generated it; otherwise the nearest wider
 * generated size, then the widest narrower one, then the original. Sizes can
 * be missing on documents uploaded before a size was added.
 */
export function pickImageSize(
  media: MediaImage,
  name: ImageSizeName,
): PickedImage | null {
  const wanted = media.sizes?.[name];
  if (usable(wanted)) return pick(wanted);

  const candidates = Object.values(media.sizes ?? {})
    .filter(usable)
    .toSorted((a, b) => a.width - b.width);
  const fallback =
    candidates.find((size) => size.width >= IMAGE_SIZES[name]) ??
    candidates.at(-1);
  if (fallback) return pick(fallback);

  return usable(media) ? pick(media) : null;
}

function pick(size: PickedImage): PickedImage {
  return { url: size.url, width: size.width, height: size.height };
}
